pin_problem() {   # pin_problem <NAME> <value> <hex length>: rc 0 = the pin cannot be used (prints why)
  local re="^[0-9a-f]{$3}\$"
  case $2 in
    *'<<'*|'') echo "$1 is still the placeholder: it must be set to a $3-hex value before a real run (LAUNCH.txt says who sets it and when)"; return 0 ;;
  esac
  [[ $2 =~ $re ]] && return 1
  echo "$1 is not a $3-hex value: $2"; return 0
}
trainer_pin_problem() { pin_problem LAUNCH_TRAINER_SHA "$LAUNCH_TRAINER_SHA" 64; }
model_pin_problem() { pin_problem LAUNCH_MODEL_SHA "$LAUNCH_MODEL_SHA" 64; }
commit_pin_problem() { pin_problem LAUNCH_COMMIT "$LAUNCH_COMMIT" 40; }
pin_vars_check() {   # the real run's early refusal: nothing is waited for, taken or shipped while ANY of the five pins is unset or malformed
  local w bad=0
  w=$(commit_pin_problem) && { echo "ZZV8FMINI-STOP $w"; bad=1; }
  w=$(trainer_pin_problem) && { echo "ZZV8FMINI-STOP $w"; bad=1; }
  w=$(model_pin_problem) && { echo "ZZV8FMINI-STOP $w"; bad=1; }
  w=$(pin_problem PREREG_SHA "$PREREG_SHA" 64) && { echo "ZZV8FMINI-STOP $w"; bad=1; }
  w=$(pin_problem READER_SHA "$READER_SHA" 64) && { echo "ZZV8FMINI-STOP $w"; bad=1; }
  return $bad
}
blob_sha() {   # blob_sha <git ref | tree ROOT> <mode git|tree> <path>: sha256 of the file at the tip (git) or in the tree
  if [ "$2" = tree ]; then sha256sum "$1/$3" 2>/dev/null | cut -c1-64; else git -C $MIRROR show "$1:$3" 2>/dev/null | sha256sum | cut -c1-64; fi
}
lever_check() {   # lever_check <git tip | tree ROOT>: 0 iff every LEVER pattern is in its file AND the trainer's and the model's sha256 are the pinned ones (git mode: AND the pinned landed commit is an ancestor of the tip)
  local mode=$1 ref=$2 rec f pat miss=0 got w
  w=$(trainer_pin_problem) && { echo "MISSING $w"; miss=$((miss+1)); }
  w=$(model_pin_problem) && { echo "MISSING $w"; miss=$((miss+1)); }
  for rec in "${LEVER[@]}"; do
    f=${rec%%|*}; pat=${rec#*|}
    if [ "$mode" = tree ]; then grep -qE -- "$pat" "$ref/$f" 2>/dev/null; else git -C $MIRROR show "$ref:$f" 2>/dev/null | grep -qE -- "$pat"; fi \
      || { echo "MISSING in $f: $pat"; miss=$((miss+1)); }
  done
  if ! trainer_pin_problem >/dev/null; then
    got=$(blob_sha "$ref" "$mode" stack/scripts/v8f_mini_train.py)
